-- Philippine Real Estate Sales Playbook Seed Data
-- Run AFTER sales_playbooks.sql (table + RLS must exist).
-- Creates 10 starter playbooks for the Philippine market.
-- Safe to re-run: upgrades legacy CHECK constraints and skips playbooks whose
-- title already exists (the table has no unique key, so "on conflict do
-- nothing" used to insert all ten again on every run).

begin;

-- ── Upgrade constraints on pre-existing tables ─────────────────────────
-- create table if not exists does NOT update an already-deployed table,
-- so older deployments keep the legacy domain lists. Drop and re-add.
alter table public.sales_playbooks drop constraint if exists sales_playbooks_category_valid;
alter table public.sales_playbooks drop constraint if exists sales_playbooks_stage_valid;
alter table public.sales_playbooks drop constraint if exists sales_playbooks_property_type_valid;

-- Remove rows using retired values so the new constraints can be applied.
delete from public.sales_playbooks
  where category not in ('OFW Buyer', 'First-Time Homebuyer', 'End-User', 'Investor', 'Balikbayan', 'Relocating Expat', 'Corporate Lease', 'Developer Bulk')
     or sales_stage not in ('Lead Generation', 'Initial Consultation', 'Property Matching', 'Site Viewing', 'Price Negotiation', 'Reservation', 'Contract to Sell', 'Financing', 'Turnover', 'Post-Sale')
     or property_type not in ('Condominium', 'House & Lot', 'Townhouse', 'Shophouse', 'Lot Only', 'Warehouse', 'Mixed-Use', 'Farm Lot');

alter table public.sales_playbooks add constraint sales_playbooks_category_valid
  check (category in ('OFW Buyer', 'First-Time Homebuyer', 'End-User', 'Investor', 'Balikbayan', 'Relocating Expat', 'Corporate Lease', 'Developer Bulk'));
alter table public.sales_playbooks add constraint sales_playbooks_stage_valid
  check (sales_stage in ('Lead Generation', 'Initial Consultation', 'Property Matching', 'Site Viewing', 'Price Negotiation', 'Reservation', 'Contract to Sell', 'Financing', 'Turnover', 'Post-Sale'));
alter table public.sales_playbooks add constraint sales_playbooks_property_type_valid
  check (property_type in ('Condominium', 'House & Lot', 'Townhouse', 'Shophouse', 'Lot Only', 'Warehouse', 'Mixed-Use', 'Farm Lot'));
-- ────────────────────────────────────────────────────────────────────────

insert into public.sales_playbooks (title,summary,category,sales_stage,property_type,target_customer,status,sections,sort_order)
select v.title, v.summary, v.category, v.sales_stage, v.property_type, v.target_customer, v.status, v.sections::jsonb, v.sort_order::int from (values (
  $$OFW Pre-Selling Condo Guide$$,
  $$Step-by-step playbook for selling pre-selling condominiums to Overseas Filipino Workers.$$,
  $$OFW Buyer$$,
  $$Lead Generation$$,
  $$Condominium$$,
  $$OFW working abroad (sea-based or land-based)$$,
  $$active$$,
  $${"opening":"Kumusta! Many OFW clients start with a reservation of P20,000-P50,000. Which country are you in and when is your next vacation?","qualification":"[ ] Employment country and contract duration\n[ ] Monthly salary range (USD, SAR, HKD, SGD, JPY)\n[ ] Target move-in date\n[ ] Preferred location: Metro Manila, Cavite, Laguna, Clark\n[ ] Budget: P2M-P5M (studio), P4M-P8M (1BR-2BR)\n[ ] Payment mode preference\n[ ] Pag-IBIG membership status\n[ ] Co-buyer in Philippines?\n[ ] Previous property ownership\n[ ] Timeline for reservation","propertyDetails":"Pre-selling condo Metro Manila:\n- Studio: 22-28 sqm, P2.5M-P3.8M\n- 1-Bedroom: 32-42 sqm, P3.8M-P5.5M\n- 2-Bedroom: 52-68 sqm, P5.5M-P8.5M\n\nPayment:\n- Reservation: P20,000-P50,000\n- Monthly: P8,000-P25,000 during construction (2-4 years)\n- Balance: bank (7.5%-9.5%) or in-house (12%-14%)\n\nKey points:\n- 10%-20% appreciation by turnover\n- Rental yield 6%-8% (BGC, Makati, Ortigas)\n- Up to 40% foreign-owned building\n- OFW payment holidays available","objections":[{"trigger":"Hindi pa ako sure kung gusto ko mag-invest.","response":"Pre-selling gives you flexibility -- lock in todays price with 2-4 years to decide. Reservation refundable within 7 days."},{"trigger":"Mahal naman! Nasa P3M ang studio.","response":"That unit in 3 years will be P3.8M-P4.2M. Monthly during construction is only P10,000. You own a prime Metro Manila asset."},{"trigger":"Hindi naman ako sure kung safe ang pera ko.","response":"Our developers are DHSUD-accredited, SEC-registered, with 10+ projects delivered. I can send track record and certificates."},{"trigger":"Wala naman akong kakilala sa Pilipinas.","response":"We handle everything remotely. Notarization at the nearest consulate, special power of attorney if needed."},{"trigger":"Ang tagal pa bago matapos.","response":"Construction is your advantage. Downpayment spread 36-48 months. By turnover you paid 20%-30% and unit appreciated."}],"followUp":"Day 1: Send brochure via Viber/WhatsApp\nDay 3: Follow up\nDay 7: Share OFW success stories\nDay 14: Free Zoom with developer\nDay 21: Limited units at current price\nDay 30: Final offer to reserve on their behalf","closing":"1. Assumptive: Reservation is P30,000. Shall I send bank details?\n2. Urgency: P200K increase next month. Reserve this week.\n3. Comparison: BGC unit P120K/sqm vs this P95K/sqm.\n4. Risk-reversal: 7-day refund. Zero risk.","coaching":"1. Communicate in their timezone.\n2. Use Viber/WhatsApp.\n3. Match remittance schedule.\n4. Be patient.\n5. Know Pag-IBIG overseas program.\n6. Verify developer credentials.\n7. Connect with other OFW buyers."}$$,
  1
)) v(title,summary,category,sales_stage,property_type,target_customer,status,sections,sort_order)
where not exists (select 1 from public.sales_playbooks p where p.title = v.title);

insert into public.sales_playbooks (title,summary,category,sales_stage,property_type,target_customer,status,sections,sort_order)
select v.title, v.summary, v.category, v.sales_stage, v.property_type, v.target_customer, v.status, v.sections::jsonb, v.sort_order::int from (values (
  $$First-Time Buyer: House and Lot$$,
  $$Guide for first-time Filipino homebuyers purchasing a house and lot via Pag-IBIG and bank financing.$$,
  $$First-Time Homebuyer$$,
  $$Initial Consultation$$,
  $$House & Lot$$,
  $$Young Filipino professional or couple, 25-40, first purchase$$,
  $$active$$,
  $${"opening":"Buying your first home is a huge milestone. Are you renting? How much do you pay? Ownership can cost less than renting.","qualification":"[ ] Monthly household income\n[ ] Current rental expense\n[ ] Preferred location: Cavite, Laguna, Bulacan, Rizal\n[ ] Budget: P1.5M-P3M or P3M-P6M\n[ ] Employment type\n[ ] Pag-IBIG membership status\n[ ] Move-in timeline\n[ ] Family size\n[ ] Downpayment savings (10%-20%)","propertyDetails":"House and lot (Cavite/Laguna/Bulacan):\n- Rowhouse: 36 sqm lot, P1.8M-P2.2M\n- Townhouse: 40 sqm lot, P2.2M-P2.8M\n- Single attached: 80 sqm lot, P3.2M-P4.5M\n- Single detached: 120 sqm lot, P4.5M-P6.5M\n\nFinancing:\n- Pag-IBIG: up to P6M, 8%-10.5%, 30-year max\n- Bank: up to P10M, 7%-9%, 20-year term\n- In-house: 12%-18%, 5-10 year term","objections":[{"trigger":"Hindi pa ako ready.","response":"If you pay P8,000-P12,000 rent, that same amount is your mortgage. After 20-30 years you own the asset. With rent, nothing."},{"trigger":"Wala akong pang-downpayment.","response":"Many developers offer zero or low downpayment promos. Some need only P10,000-P20,000 reservation spread over 24-48 months."},{"trigger":"Baka hindi ma-approve ang loan ko.","response":"If income is P25,000+ with 24 months Pag-IBIG, approval is likely. I will help prepare your complete requirements."},{"trigger":"Mas mura pa ang apartment.","response":"A P2M house via Pag-IBIG costs P12,500/month for 25 years. Similar apartment P8,000-P10,000/month forever. After 25 years the house is yours."},{"trigger":"Malayo sa Manila.","response":"CALABARZON has CALAX, LRT-1 Cavite extension. Cavite to Makati is 45-60 minutes. Better air and space."}],"followUp":"Day 1: Send Pag-IBIG loan calculator\nDay 3: Share site photos\nDay 5: Pag-IBIG membership questions\nDay 7: Documentary requirements checklist\nDay 14: Free site tripping with shuttle\nDay 21: Limited-time promo\nDay 30: Help with Pag-IBIG registration","closing":"1. Financial: P11,800/month via Pag-IBIG for 3BR vs P14,000 rent for 2BR condo.\n2. Emotional: Your own house, kids own room, backyard.\n3. Urgency: 15 units at Phase 2 pricing. Next batch P200,000 more.\n4. Social proof: A teacher earning P32,000/month just bought via Pag-IBIG.","coaching":"1. Be patient with questions.\n2. Use Taglish.\n3. Show actual numbers.\n4. Explain Pag-IBIG step by step.\n5. Offer site tripping.\n6. Meet both partners.\n7. Follow up weekly."}$$,
  2
)) v(title,summary,category,sales_stage,property_type,target_customer,status,sections,sort_order)
where not exists (select 1 from public.sales_playbooks p where p.title = v.title);

insert into public.sales_playbooks (title,summary,category,sales_stage,property_type,target_customer,status,sections,sort_order)
select v.title, v.summary, v.category, v.sales_stage, v.property_type, v.target_customer, v.status, v.sections::jsonb, v.sort_order::int from (values (
  $$Shophouse Investment Playbook$$,
  $$Guide for selling shophouse properties to investors. Covers dual-income potential and ROI projections.$$,
  $$Investor$$,
  $$Property Matching$$,
  $$Shophouse$$,
  $$Investor looking for income-generating property$$,
  $$active$$,
  $${"opening":"A shophouse gives you two income streams from a single title -- commercial rental downstairs and residential rental upstairs. Are you familiar with shophouse yields?","qualification":"[ ] Investment budget: P5M-P15M\n[ ] Preferred location\n[ ] Investment goal: income, appreciation, or both\n[ ] Existing portfolio\n[ ] Cash or financing?\n[ ] Timeline for income\n[ ] Business for ground floor?\n[ ] Risk tolerance\n[ ] Target tenant profile\n[ ] Minimum yield requirement","propertyDetails":"Shophouse specifications:\n- Ground floor: 40-80 sqm commercial\n- Second floor: 50-80 sqm residential, 2BR/1TB\n- Total: 120-200 sqm per unit\n\nPricing: P5.5M-P12M\nPre-selling discount: 10%-15%\n\nIncome potential:\n- Ground floor: P25,000-P60,000/month\n- Upper floor: P15,000-P30,000/month\n- Combined yield: 8%-12% annually\n- Capital appreciation: 10%-20% per year","objections":[{"trigger":"Mas kilala ko ang condo investment.","response":"A P6M condo yields 5%-6%. A P6M shophouse yields 8%-12% with double the income streams. Same capital, higher return."},{"trigger":"Nakakatakot mag-invest sa commercial.","response":"We only recommend high-foot-traffic corridors with proven demand. We provide tenant sourcing. Last project: all units leased within 60 days."},{"trigger":"Mahal ang shophouse vs condo.","response":"Compare yield: P6M condo at P18K rent = 3.6%. P8M shophouse at P45K combined = 6.75%. Nearly double the return."},{"trigger":"Pwede ba mag-loan?","response":"Bank financing at 7%-9% over 10-15 years. With P40K rental income and P25K amortization, you are cash-flow positive from month one."},{"trigger":"Ano ang guarantee na tataas ang value?","response":"Shophouses in emerging corridors showed 10%-20% appreciation over 5 years. MSME growth drives demand; supply is limited."}],"followUp":"Day 1: Send yield comparison sheet\nDay 3: Share foot traffic data\nDay 7: Video walkthrough of model unit\nDay 14: Meeting with current tenants\nDay 21: Financing options\nDay 30: Remaining inventory and price history","closing":"1. ROI: P8M investment, P540K rental, 12% appreciation = 18.75% ROI year one.\n2. Portfolio: Shophouse diversifies beyond condos.\n3. Urgency: Only 8 units left in this phase.\n4. Cash-flow: Rental covers amortization plus P15K surplus.","coaching":"1. Lead with yield.\n2. Prepare 10-year cash flow projection.\n3. Show comparable rental rates.\n4. Know zoning restrictions.\n5. Understand condo vs lot title.\n6. Offer tenant sourcing.\n7. Build investor relationships."}$$,
  3
)) v(title,summary,category,sales_stage,property_type,target_customer,status,sections,sort_order)
where not exists (select 1 from public.sales_playbooks p where p.title = v.title);

insert into public.sales_playbooks (title,summary,category,sales_stage,property_type,target_customer,status,sections,sort_order)
select v.title, v.summary, v.category, v.sales_stage, v.property_type, v.target_customer, v.status, v.sections::jsonb, v.sort_order::int from (values (
  $$Balikbayan Condo Buying Guide$$,
  $$Playbook for selling condominiums to Balikbayans returning permanently or semi-permanently.$$,
  $$Balikbayan$$,
  $$Property Matching$$,
  $$Condominium$$,
  $$Filipino returning from abroad planning to retire or settle in the Philippines$$,
  $$active$$,
  $${"opening":"Welcome home! A lot of Balikbayans look for a condo as their home base -- low maintenance, secure, and in a community with everything nearby. Metro Manila, Cebu, Davao, or Clark?","qualification":"[ ] Current country and how long abroad\n[ ] Returning permanently or semi-annually?\n[ ] Preferred city or region\n[ ] Budget: P3M-P8M\n[ ] Property use: primary, vacation, or rental when away\n[ ] Dual citizenship status (RA 9225)\n[ ] Existing property in Philippines?\n[ ] Preferred condo size\n[ ] Proximity needs: hospital, mall, airport\n[ ] Move-in timeline","propertyDetails":"Balikbayan condo options:\n- Makati: P5M-P8M, 1BR-2BR, near Ayala Mall, hospitals\n- BGC: P6M-P10M, 2BR, premium amenities, international community\n- Cebu IT Park: P4M-P6M, 1BR-2BR, tech hub, hospitals\n- Clark: P3M-P5M, 1BR-2BR, airport access, retirement-friendly\n- Davao: P3M-P5M, 1BR-2BR, low crime, nature access\n\nFeatures Balikbayans care about:\n- 24/7 security with CCTV and backup generator\n- Elevators for aging in place\n- Near hospitals and malls\n- Pet-friendly buildings\n- Property management for when abroad\n\nRA 9225: Dual citizens can own land and property without restrictions.","objections":[{"trigger":"Baka hindi ko na kailangan kasi babalik na ako sa abroad.","response":"A condo is perfect -- vacation home when you visit, rent it out when away. Many Balikbayans earn P1,500-P3,000/night on Airbnb when not using it."},{"trigger":"Mahal ang condo sa Makati/BGC.","response":"A P6M 1BR in BGC rents for P35,000-P45,000/month -- 7%-9% yield. Premium address, international amenities, community of fellow Balikbayans."},{"trigger":"Hindi ko alam ang process dito sa Pinas.","response":"We handle everything: reservation, documentation, financing, condo turnover. For dual citizens under RA 9225, just need dual citizenship certificate and valid ID."},{"trigger":"Sana bahay na lang para may lupa.","response":"A condo is better for Balikbayans who split time between countries. No maintenance, no yard, security built-in, no caretaker needed. Lock-and-leave lifestyle."},{"trigger":"Baka scam lang kasi online ako nag-inquire.","response":"We are SEC-registered with HLURB-accredited projects. I can send SEC registration, developer HLURB license, and Balikbayan client references."}],"followUp":"Day 1: Send personalized condo shortlist with photos\nDay 3: Share virtual tour videos\nDay 7: Call about travel dates for site visit\nDay 14: Send RA 9225 property ownership checklist\nDay 21: Airport pickup + site tripping offer\nDay 30: Share a Balikbayan success story","closing":"1. Lifestyle: Next trip home, walk into your own place instead of a hotel.\n2. Dual citizenship: Under RA 9225, same property rights as any Filipino.\n3. Urgency: Rare corner unit with city view at P6.5M. Once reserved, gone.\n4. Peace-of-mind: Property management when abroad. Monthly reports and deposits.","coaching":"1. Respect their time -- often on a short visit.\n2. Understand RA 9225 -- major concern.\n3. Offer airport pickup + site tripping combo.\n4. Address scam concern early.\n5. Know Balikbayan tax privileges.\n6. Familiar with condo rules: pets, rentals, Airbnb.\n7. Offer property management.\n8. Connect with Balikbayan community.\n9. Follow up via email."}$$,
  4
)) v(title,summary,category,sales_stage,property_type,target_customer,status,sections,sort_order)
where not exists (select 1 from public.sales_playbooks p where p.title = v.title);

insert into public.sales_playbooks (title,summary,category,sales_stage,property_type,target_customer,status,sections,sort_order)
select v.title, v.summary, v.category, v.sales_stage, v.property_type, v.target_customer, v.status, v.sections::jsonb, v.sort_order::int from (values (
  $$End-User Townhouse Guide$$,
  $$Playbook for selling townhouses to end-user families upgrading from apartments or condominiums.$$,
  $$End-User$$,
  $$Site Viewing$$,
  $$Townhouse$$,
  $$Filipino family upgrading from condo or apartment$$,
  $$active$$,
  $${"opening":"You mentioned you are in a 2BR condo with two kids -- I can see why you want more space. A townhouse gives you your own front door, a small yard, and 3 bedrooms. Want to visit a unit this weekend?","qualification":"[ ] Current living situation\n[ ] Number of children and ages\n[ ] Preferred location: near work, school, family\n[ ] Budget: P3M-P6M\n[ ] Monthly household income: P50,000+\n[ ] Preferred commute time\n[ ] Space requirements: bedrooms, parking, yard\n[ ] Community needs: school, playground, security\n[ ] Timeline: ASAP or within 6 months\n[ ] Financing preference","propertyDetails":"Townhouse options:\n- Inner unit: 40 sqm lot, 45 sqm floor, 3BR/2TB, P3.5M-P4.2M\n- End unit: 50 sqm lot, 52 sqm floor, 3BR/2TB, P4.2M-P5M\n- Corner unit: 70 sqm lot, 60 sqm floor, 3BR/2TB + carport, P5M-P6M\n\nWhy townhouse over condo:\n- Your own lot -- land appreciates\n- No monthly association dues (or very low)\n- Privacy -- no neighbors above or below\n- Small yard or service area\n- Subdivision community with amenities\n\nFinancing:\n- Pag-IBIG: P3.5M loan, P14,500/month for 25 years\n- Bank: P4M loan, P16,200/month for 20 years\n- Downpayment: 10%-20% over 12-24 months","objections":[{"trigger":"Mas malapit ang condo sa work ko.","response":"Think about the next 10 years. Kids need their own rooms, yard to play in. A townhouse in Cavite with 45-minute commute gives 3x the space at the same monthly cost."},{"trigger":"Baka hindi kaya ng budget ko.","response":"A P3.8M townhouse via Pag-IBIG is P15,800/month. Your current condo rent is P14,000. For P1,800 more, you get a 3BR townhouse with your own lot."},{"trigger":"Ayoko ng malayo sa city.","response":"Many townhouse developments are 30-45 minutes from Metro Manila. Cavite to Makati is 40 minutes via CAVITEX. Fresh air, less traffic, real community."},{"trigger":"Mas gusto ko condo kasi may gym at pool.","response":"Subdivisions have amenities too -- clubhouse, basketball court, playground. Some have pools. Not shared with 500 other units. Get a gym membership nearby for P1,500/month."},{"trigger":"Baka hindi tumataas ang value.","response":"Townhouse values in Cavite and Laguna appreciated 10%-15% annually for 5 years. A P3M unit in 2020 is now P4.2M. Land is the primary driver."}],"followUp":"Day 1: Send townhouse brochure with floor plans\nDay 3: Commute time comparison\nDay 5: Nearby school and hospital list\nDay 7: Weekend site tripping with free shuttle\nDay 14: Pag-IBIG loan calculator\nDay 21: Community photos -- families, events\nDay 30: Limited end/corner units available","closing":"1. Family: Kids grow up with their own room, backyard, safe neighborhood.\n2. Financial: P15,800/month for 3BR townhouse vs P14,000 rent for 2BR condo.\n3. Upgrade: 5 years renting = P840,000 with zero equity. Townhouse builds P1.2M equity.\n4. Urgency: 4 end units remain. End units sell out first.","coaching":"1. Focus on family upgrade story.\n2. Always do rent vs own comparison.\n3. Show commute realistically.\n4. Highlight nearby schools.\n5. Bring family to site visit.\n6. Discuss community and HOA.\n7. Be honest about traffic.\n8. Show appreciation data.\n9. Help with Pag-IBIG application."}$$,
  5
)) v(title,summary,category,sales_stage,property_type,target_customer,status,sections,sort_order)
where not exists (select 1 from public.sales_playbooks p where p.title = v.title);

insert into public.sales_playbooks (title,summary,category,sales_stage,property_type,target_customer,status,sections,sort_order)
select v.title, v.summary, v.category, v.sales_stage, v.property_type, v.target_customer, v.status, v.sections::jsonb, v.sort_order::int from (values (
  $$Relocating Expat Condo Guide$$,
  $$Playbook for selling condominiums to foreign expats relocating to the Philippines.$$,
  $$Relocating Expat$$,
  $$Price Negotiation$$,
  $$Condominium$$,
  $$Foreign national relocating to the Philippines for work or retirement$$,
  $$active$$,
  $${"opening":"Welcome to the Philippines! I specialize in helping expats find the right condo. Are you relocating for work, retirement, or a mix of both?","qualification":"[ ] Nationality and current country\n[ ] Reason: work, retirement, business, digital nomad\n[ ] Preferred city: Makati, BGC, Ortigas, Cebu, Clark\n[ ] Budget: P5M-P15M\n[ ] Unit preference: studio, 1BR, 2BR, penthouse\n[ ] Lease vs buy decision\n[ ] Visa type: 9(g), SRRV, 13(a)\n[ ] Amenities priority\n[ ] Move-in timeline: immediate or within 3 months\n[ ] Furniture preference","propertyDetails":"Expat-friendly condos:\n- Makati CBD: P6M-P12M, 1BR-2BR, walkable to BPO offices\n- BGC: P7M-P15M, 1BR-2BR, international community\n- Ortigas: P5M-P8M, 1BR-2BR, near SM Megamall\n- Cebu IT Park: P4M-P7M, studio-2BR, tech hub\n- Clark Freeport: P4M-P6M, 1BR-2BR, airport access\n\nForeign ownership rules:\n- Foreigners can own condo units (RA 4726)\n- 40% foreign ownership cap per building\n- Foreigners CANNOT own land\n- Condo title in foreigner name -- full legal ownership\n\nVisa considerations:\n- SRRV: $1,500-$1,500 deposit, unlimited stay\n- 9(g) Work Visa: employer-sponsored, renewable\n- 13(a) Spouse Visa: married to Filipino, 10-year","objections":[{"trigger":"Can foreigners actually own property here?","response":"Yes! Under RA 4726, foreigners directly own condo units. The title is in your name. The only restriction is land ownership. Many expats in Makati and BGC own their units."},{"trigger":"I am not sure about the long-term visa.","response":"SRRV is one of the best retirement visas in Asia -- $1,500 deposit for age 35+. Indefinite stay, multiple entry, no reporting requirements."},{"trigger":"The Philippines seems risky for investment.","response":"Philippine condo prices appreciated 6%-10% annually for the past decade. Makati and BGC are among the most stable markets in Southeast Asia."},{"trigger":"I would rather rent for now.","response":"Renting 1BR in BGC costs P35,000-P50,000/month. Over 5 years that is P2.1M-P3M with zero equity. Buying costs about the same monthly but builds P2M+ equity."},{"trigger":"I need to check with my embassy first.","response":"Absolutely. I can provide RA 4726 summary, sample foreign-name title, and developer accreditation documents. Take all the time you need."}],"followUp":"Day 1: Send expat property guide (PDF) with foreign ownership rules\nDay 3: Curated shortlist of 3-5 condos\nDay 7: Zoom call for legal questions\nDay 14: Sample condo title with foreign name\nDay 21: Virtual or in-person tour\nDay 30: Follow up on embassy/accountant questions","closing":"1. Legal: Complete documentation prepared. Shall we proceed with reservation?\n2. Financial: Renting P45K/month with nothing vs buying P48K/month with real ownership.\n3. Lifestyle: 24/7 concierge, gym, rooftop pool, 15 international restaurants nearby.\n4. Risk-reversal: 7-day cooling-off. Full refund if anything feels wrong.","coaching":"1. Lead with legality -- foreign ownership rights first.\n2. Provide written documentation.\n3. Understand visa types.\n4. Know embassy locations and SRRV process.\n5. Highlight international community.\n6. Be aware of cultural differences.\n7. Connect with expat communities.\n8. Know banking requirements for foreigners.\n9. Follow up via email."}$$,
  6
)) v(title,summary,category,sales_stage,property_type,target_customer,status,sections,sort_order)
where not exists (select 1 from public.sales_playbooks p where p.title = v.title);

insert into public.sales_playbooks (title,summary,category,sales_stage,property_type,target_customer,status,sections,sort_order)
select v.title, v.summary, v.category, v.sales_stage, v.property_type, v.target_customer, v.status, v.sections::jsonb, v.sort_order::int from (values (
  $$Corporate Lease Playbook$$,
  $$Playbook for leasing commercial spaces to BPO companies, tech startups, clinics, and MSMEs.$$,
  $$Corporate Lease$$,
  $$Initial Consultation$$,
  $$Mixed-Use$$,
  $$BPO/IT company, clinic, F&B chain, or MSME looking for commercial space$$,
  $$active$$,
  $${"opening":"Before we discuss specific units, I would like to understand your business needs. How many staff will occupy the space and what is your ideal move-in timeline?","qualification":"[ ] Company name and industry\n[ ] Number of employees\n[ ] Space requirement in sqm\n[ ] Budget per sqm: P500-P1,000 (BPO), P800-P1,500 (office), P1,200-P2,500 (retail)\n[ ] Preferred location\n[ ] Lease term: 1, 3, or 5 years\n[ ] Move-in timeline\n[ ] Fit-out requirements\n[ ] Parking slots needed\n[ ] Advance payment and deposit budget\n[ ] Current lease expiration\n[ ] Decision-maker identity","propertyDetails":"Commercial space options:\n- BPO-ready: 100-500 sqm, P600-P900/sqm/month, pre-wired\n- Corporate office: 200-1,000 sqm, P900-P1,500/sqm/month\n- Retail: 50-200 sqm, P1,200-P2,500/sqm/month, ground floor\n- Medical suite: 80-300 sqm, P800-P1,200/sqm/month\n- Co-working: 10-50 desks, P5,000-P12,000/desk/month\n\nLease structures:\n- Standard: 12 months, 2 months advance, 2 months deposit\n- BPO package: 36 months, 1 month advance, 3 months deposit, 60-day fit-out\n- MSME starter: 12 months, 1 month advance, 2 months deposit, discounted","objections":[{"trigger":"The rate is too high vs other buildings.","response":"Let me show total cost: 24/7 AC, generator, security, parking, gym, maintenance all included. Many cheaper buildings charge extra. Our effective rate is competitive."},{"trigger":"We need a shorter lease.","response":"We offer 12-month leases at P950/sqm. We also have co-working at P8,000/desk/month with no long-term contract. What is your ideal timeline?"},{"trigger":"We need fit-out time before paying rent.","response":"All leases include fit-out period. 36-month leases get 60 days rent-free. 12-month leases get 30 days. Install IT, furniture, equipment without paying rent."},{"trigger":"Our budget only allows P500/sqm.","response":"At P500/sqm, I recommend our co-working spaces or Clark emerging business district. Clark offers BPO-ready spaces at P400-P600/sqm with airport proximity."},{"trigger":"We are a startup, might not stay long.","response":"MSME starter package: 12-month lease, 1 month advance, 2 months deposit. Discounted rate. If you grow, priority for adjacent units. Risk is low."}],"followUp":"Day 1: Send space layout options and floor plans\nDay 3: Lease rate comparison sheet\nDay 5: Sample lease contract\nDay 7: Site visit with building manager\nDay 14: Tenant references from similar businesses\nDay 21: Customized lease proposal with fit-out period\nDay 30: Decision timeline and early commitment discount","closing":"1. ROI: 50 staff at P800/sqm = P1,600 per employee -- less than a parking slot in BGC.\n2. Urgency: 3 available units, 2 other companies evaluating. Next availability in 6 months.\n3. Total cost: P800/sqm all-in vs P650/sqm + P150/sqm extras. Real cost is the same.\n4. Partnership: 36-month lease gets 60-day fit-out, 2 free parking, 5% year-2 discount.","coaching":"1. Know competitor rates.\n2. Understand the client industry.\n3. Meet the decision-maker.\n4. Prepare total cost analysis.\n5. Know fit-out requirements.\n6. Offer flexible terms for startups.\n7. Build tenant relationships.\n8. Know zoning and allowed uses.\n9. Always prepare written proposal."}$$,
  7
)) v(title,summary,category,sales_stage,property_type,target_customer,status,sections,sort_order)
where not exists (select 1 from public.sales_playbooks p where p.title = v.title);

insert into public.sales_playbooks (title,summary,category,sales_stage,property_type,target_customer,status,sections,sort_order)
select v.title, v.summary, v.category, v.sales_stage, v.property_type, v.target_customer, v.status, v.sections::jsonb, v.sort_order::int from (values (
  $$Developer Bulk Sales Guide$$,
  $$Playbook for bulk property sales to small/mid-size developers and housing cooperatives.$$,
  $$Developer Bulk$$,
  $$Property Matching$$,
  $$Mixed-Use$$,
  $$Small/mid-size developer or housing cooperative$$,
  $$active$$,
  $${"opening":"We work with developers and cooperatives who acquire units at preferential pricing. How many units are you targeting and what is your resale timeline?","qualification":"[ ] Developer company and SEC registration\n[ ] Project type: resale, employee housing, cooperative\n[ ] Number of units: 10+, 25+, 50+\n[ ] Unit mix preference\n[ ] Budget per unit and total\n[ ] Preferred location\n[ ] Timeline: 6, 12, or 24 months\n[ ] Financing: cash, bank, or joint venture\n[ ] Previous bulk purchase experience\n[ ] End-buyer profile","propertyDetails":"Bulk pricing tiers:\n- 10-24 units: 8%-10% discount\n- 25-49 units: 10%-12% + priority selection\n- 50-99 units: 12%-15% + fit-out allowance\n- 100+ units: 15%-18% + joint venture terms\n\nUnit availability:\n- Pre-selling: P2.5M-P5M per unit\n- Ready for occupancy: P3.5M-P7M\n- Townhouse bulk: P3M-P5M (Cavite/Laguna)\n\nDeal structures:\n1. Cash: 15%-18% discount, 30-day closing\n2. Bank-assisted: 10%-12% discount\n3. Joint venture: developer builds, buyer guarantees\n4. Cooperative: pre-negotiated price per member","objections":[{"trigger":"The bulk discount is not enough.","response":"At 12% off P3M, cost is P2.64M. Resale at P3.2M = P560K margin (21%). With 25 units = P14M gross profit. What margin are you targeting?"},{"trigger":"We prefer direct negotiation.","response":"We are the authorized channel partner. Same pricing via us. We handle coordination, documentation, and title transfers for all units."},{"trigger":"What if the market drops?","response":"Pre-selling locks in today price. Protected if market drops, benefits if it rises. 2-3 years to spread payments."},{"trigger":"Members are not sure about the developer.","response":"Site visit for board to meet developer, inspect projects, review SEC/DHSUD registrations. Reference list of other cooperatives provided."},{"trigger":"We need the financial model first.","response":"Full financial model: unit costs, resale projections, total investment, ROI, break-even. Sensitivity analyses available."}],"followUp":"Day 1: Bulk pricing matrix and inventory\nDay 3: Developer credentials and track record\nDay 7: Customized financial model\nDay 14: Site visit with developer team\nDay 21: Formal proposal\nDay 30: Board follow-up with additional discount","closing":"1. Volume: 50 units at P2.55M vs P3M retail = P22.5M savings.\n2. Timeline: Phase 2 at 10% higher next month.\n3. Partnership: Title transfers, coordination, marketing.\n4. Risk-free: Buyback guarantee on first 5 units.","coaching":"1. Prepare financial model.\n2. Know developer track record.\n3. Understand buyer business model.\n4. Prepare tiered pricing.\n5. Offer buyback guarantees.\n6. Build developer relationships.\n7. Know title transfer process.\n8. Offer marketing support.\n9. Have formal proposal ready."}$$,
  8
)) v(title,summary,category,sales_stage,property_type,target_customer,status,sections,sort_order)
where not exists (select 1 from public.sales_playbooks p where p.title = v.title);

insert into public.sales_playbooks (title,summary,category,sales_stage,property_type,target_customer,status,sections,sort_order)
select v.title, v.summary, v.category, v.sales_stage, v.property_type, v.target_customer, v.status, v.sections::jsonb, v.sort_order::int from (values (
  $$OFW Lot-Only Investment Guide$$,
  $$Playbook for selling residential lots to OFWs for land banking and future home construction.$$,
  $$OFW Buyer$$,
  $$Contract to Sell$$,
  $$Lot Only$$,
  $$OFW looking to invest in residential land$$,
  $$active$$,
  $${"opening":"Buying land while abroad is one of the smartest moves an OFW can make. Land appreciates fastest and you can build whenever ready. Specific province or want recommendations?","qualification":"[ ] Current country of employment\n[ ] Target province or area\n[ ] Budget: P500K-P3M\n[ ] Lot size: 100, 200, 500+ sqm\n[ ] Purpose: land banking, future home, farm\n[ ] Construction timeline\n[ ] Road access and utilities?\n[ ] Family in area to monitor?\n[ ] Cash or financing?\n[ ] Title type preference","propertyDetails":"Lot options:\n- Subdivision: 100-200 sqm, P3,000-P8,000/sqm, titled\n- Provincial: 200-500 sqm, P1,500-P4,000/sqm\n- Farm: 500-5,000 sqm, P800-P2,500/sqm\n- Beach/mountain: 200-1,000 sqm, P2,000-P6,000/sqm\n\nTop appreciation areas:\n- Cavite: 12%-18% annual\n- Laguna: 10%-15% annual\n- Bulacan: 8%-12% annual\n- Clark/Pampanga: 15%-20% (airport)\n- Cebu: 10%-15% annual\n\nWhy lot-only for OFWs:\n- No monthly amortization (cash)\n- No maintenance costs\n- Appreciates 10%-18% annually\n- Build when ready\n- Collateral for future loans\n- Inflation hedge","objections":[{"trigger":"Hindi tumataas ang value ng lupa.","response":"Philippine land appreciated 10%-18% annually. A 200 sqm lot at P1.5M in 2019 is now P2.8M. P1.3M equity doing nothing."},{"trigger":"Wala akong planong gumawa ng bahay.","response":"Buy now, let it appreciate, build later. Land doubles in value over 5-10 years. You already own the most expensive part."},{"trigger":"Paano ko mamomonitor from abroad?","response":"Trusted family member visits quarterly. Perimeter fence or marker. Lot plan with GPS coordinates. Join homeowners association."},{"trigger":"Baka ma-scam ako sa lupa.","response":"Only titled lots with verified TCT/CCT. Title verified at Register of Deeds before payment. Escrow for payments. Legal team reviews all documents."},{"trigger":"Mas maganda siguro condo.","response":"Condos for rental income, lots for wealth. Best portfolio has both: condos for income, lots for unlimited appreciation potential."}],"followUp":"Day 1: Send lot options with prices, photos, title status\nDay 3: Appreciation data for the area (5-year trend)\nDay 5: Map with location, landmarks, access roads\nDay 7: Virtual site visit via video with family member\nDay 14: OFW success stories\nDay 21: Cash discount vs installment options\nDay 30: Limited lots in subdivision","closing":"1. Wealth: P1.5M lot in Cavite = P3M in 5 years. P1.5M pure appreciation.\n2. Legacy: Foundation of your family future home.\n3. Urgency: 8 remaining lots. Three sold last month. Price increase next quarter.\n4. Risk-free: Clean title, verified, escrow protection.\n5. Simple: Reserve P10,000, sign contract, title transfer via SPA.","coaching":"1. Verify title first.\n2. Provide GPS coordinates.\n3. Offer escrow protection.\n4. Titled vs untitled lots.\n5. Lot classification: residential vs agricultural.\n6. Family member inspection.\n7. Homeowners association.\n8. Property monitoring service.\n9. Show appreciation data.\n10. Connect with other OFW buyers."}$$,
  9
)) v(title,summary,category,sales_stage,property_type,target_customer,status,sections,sort_order)
where not exists (select 1 from public.sales_playbooks p where p.title = v.title);

insert into public.sales_playbooks (title,summary,category,sales_stage,property_type,target_customer,status,sections,sort_order)
select v.title, v.summary, v.category, v.sales_stage, v.property_type, v.target_customer, v.status, v.sections::jsonb, v.sort_order::int from (values (
  $$Warehouse Investment Guide$$,
  $$Playbook for selling warehouse and industrial spaces to logistics companies and e-commerce operators.$$,
  $$Investor$$,
  $$Property Matching$$,
  $$Warehouse$$,
  $$Logistics company, e-commerce operator, food manufacturer, or industrial investor$$,
  $$active$$,
  $${"opening":"Philippine logistics and e-commerce is growing 15%-20% annually. Warehouse demand is at an all-time high. What is your primary use and how much space do you need?","qualification":"[ ] Company name and industry\n[ ] Use: fulfillment, cold storage, distribution\n[ ] Space: 500, 1,000, 5,000+ sqm\n[ ] Budget: P5M-P50M (purchase), P250-P600/sqm/mo (lease)\n[ ] Preferred location: Cavite, Laguna, Bulacan, Clark, Subic\n[ ] Loading dock requirements\n[ ] Ceiling height: 6m, 8m, 10m+\n[ ] Power requirement: kVA capacity\n[ ] Lease term: 3, 5, or 10 years\n[ ] Expansion needs\n[ ] Occupancy timeline","propertyDetails":"Warehouse options:\n- Small: 500-1,000 sqm, P15M-P30M\n- Mid-size: 1,000-3,000 sqm, P30M-P80M\n- Large: 3,000-10,000 sqm, P80M-P250M\n- Cold storage: 500-2,000 sqm, P25M-P80M\n\nIndustrial park locations:\n- Cavite: P350-P500/sqm/mo, near CAVITEX\n- Laguna: P300-P450/sqm/mo, near SLEX\n- Clark: P250-P400/sqm/mo, near airport\n- Subic: P200-P350/sqm/mo, port access\n- Bulacan: P280-P400/sqm/mo, NLEX access\n\nFeatures:\n- Floor loading: 2-5 tons/sqm\n- Ceiling: 6-12 meters\n- Loading docks with hydraulic levelers\n- Power: 500-2,000 kVA\n- Fire protection: sprinkler, alarm, exits\n- 24/7 security, CCTV, perimeter fence\n- Attached office: 50-200 sqm\n\nLease-to-own:\n- 5-year lease with purchase option\n- 50% of payments credited to purchase","objections":[{"trigger":"The rate is higher vs other parks.","response":"Total cost includes security, fire protection, docks, office. Other parks charge extra. Plus location near expressway saves P15K-P25K/month in trucking."},{"trigger":"We are a startup.","response":"MSME starter: 3-year lease, 1 month advance, 2 months deposit, P300/sqm. Lease-to-own option builds equity."},{"trigger":"Cold storage cost is too high.","response":"A P30M cold storage facility generates P1.5M-P2M monthly revenue. Pays for itself in 18-24 months. Start with 500 sqm."},{"trigger":"What if we need to expand?","response":"Right of first refusal for adjacent units. Same rate for expansion. Parks in 5 locations for geographic growth."},{"trigger":"We prefer to buy.","response":"Purchase: P50M at 8% bank financing for 10 years = P600K/month. Comparable to leasing. After 10 years you own the asset."}],"followUp":"Day 1: Warehouse options with floor plans\nDay 3: Industrial park comparison sheet\nDay 5: Virtual tour of available units\nDay 7: Site visit with park manager\nDay 14: Customized lease or purchase proposal\nDay 21: Market data and rental trends\nDay 30: Decision timeline and early commitment discount","closing":"1. Demand: Warehouse demand up 25% this year. Vacancy below 5%. Lock in current rate.\n2. ROI: 1,000 sqm at P400/sqm = P400K/month vs P2M revenue = 20% of revenue.\n3. Lease-to-own: P10M in credits over 5 years. Effective price P15M for P30M asset.\n4. Partnership: Maintenance, security, expansion in 5 provinces.","coaching":"1. Lead with location economics.\n2. Understand the client industry.\n3. Total cost analysis.\n4. Know power requirements.\n5. Lease-to-own for startups.\n6. Cold storage economics.\n7. Industrial park zoning.\n8. Expansion coordination.\n9. Written proposal.\n10. Build tenant relationships."}$$,
  10
)) v(title,summary,category,sales_stage,property_type,target_customer,status,sections,sort_order)
where not exists (select 1 from public.sales_playbooks p where p.title = v.title);

commit;
